import sympy as sp
from fractions import Fraction as F
from collections import Counter
moves = [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]
sq = [(r,c) for r in range(8) for c in range(8)]
nb = {s:[(s[0]+a,s[1]+b) for a,b in moves if 0<=s[0]+a<8 and 0<=s[1]+b<8] for s in sq}
deg = {s:len(nb[s]) for s in sq}
assert Counter(deg.values()) == {2:4, 3:8, 4:20, 6:16, 8:16}
assert sum(deg.values()) == 336 == 4*2+8*3+20*4+16*6+16*8
assert all(deg[(r,c)] == 8 for r in range(2,6) for c in range(2,6))
pi = {s: F(deg[s], 336) for s in sq}
for v in sq:
    assert sum(pi[u]*F(1, deg[u]) for u in nb[v]) == pi[v]
c = (0,0)
others = [s for s in sq if s != c]; oi = {s:i for i,s in enumerate(others)}
A = sp.zeros(63, 63)
for s in others:
    A[oi[s], oi[s]] += 1
    for t in nb[s]:
        if t != c: A[oi[s], oi[t]] -= sp.Rational(1, deg[s])
h = A.LUsolve(sp.ones(63, 1))
ret = 1 + sum(sp.Rational(1, deg[c])*h[oi[t]] for t in nb[c])
assert ret == 168 == F(336, deg[c])
assert all((s[0]+s[1]) % 2 != (t[0]+t[1]) % 2 for s in sq for t in nb[s])

from fractions import Fraction as F
f = lambda s: 'a' if s in (1,2) else 'b'
nxt = {1:2, 2:3, 3:1}
paths = [(s, nxt[s], nxt[nxt[s]]) for s in (1,2,3)]
def cond(prev, now):
    sel = [p for p in paths if f(p[0])==prev and f(p[1])==now]
    return F(sum(1 for p in sel if f(p[2])=='a'), len(sel))
assert cond('a','a') == 0 and cond('b','a') == 1

from fractions import Fraction as F
# chain on {0..100}; from 1 the first bet goes to 0 (absorbing) with prob 1/2, to 2 (not absorbing) with prob 1/2
N = 100
step = {1: {0: F(1, 2), 2: F(1, 2)}}
assert sum(pr for j, pr in step[1].items() if j in (0, N)) == F(1, 2)
for N in range(1, 30):
    for k in range(N+1):
        assert N*F(k, N) + 0*(1-F(k, N)) == k
assert 1*(100-1) == 99
